/**
 * Guards the brand assets: everything in `public/` that identifies the app.
 *
 * These files are generated by `scripts/icons/build.mjs` (macOS-only tooling)
 * and then committed, and nothing imports them — a stale, missing or
 * wrongly-sized icon fails silently: the tab shows a broken image, iOS falls
 * back to a screenshot of the page, and link previews lose their art. So the
 * bytes get asserted here, in the same spirit as tests/fonts.test.ts.
 *
 * PNG/ICO headers are parsed by hand instead of shelling out to ImageMagick, so
 * the suite stays dependency-free.
 */
import { readFileSync, statSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { inflateSync } from 'node:zlib'
import { describe, expect, it } from 'vitest'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const read = (file: string) => readFileSync(resolve(ROOT, 'public', file))
const html = readFileSync(resolve(ROOT, 'index.html'), 'utf8')
const pwaConfig = readFileSync(resolve(ROOT, 'vite.config.ts'), 'utf8')

/** Minimal PNG reader: 8-bit RGBA, the only shape the build emits. */
function decodePng(file: string) {
  const buf = read(file)
  expect(buf.subarray(0, 8).toString('latin1'), `${file} is not a PNG`).toBe('\x89PNG\r\n\x1a\n')
  const width = buf.readUInt32BE(16)
  const height = buf.readUInt32BE(20)
  expect(buf[24], `${file} bit depth`).toBe(8)
  expect(buf[25], `${file} colour type`).toBe(6)
  const idat: Buffer[] = []
  for (let at = 8; at < buf.length; ) {
    const length = buf.readUInt32BE(at)
    const type = buf.subarray(at + 4, at + 8).toString('latin1')
    if (type === 'IDAT') idat.push(buf.subarray(at + 8, at + 8 + length))
    at += length + 12
  }
  const raw = inflateSync(Buffer.concat(idat))
  const stride = width * 4
  const pixels = Buffer.alloc(height * stride)
  for (let y = 0; y < height; y++) {
    const filter = raw[y * (stride + 1)]
    const line = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1))
    for (let x = 0; x < stride; x++) {
      const left = x >= 4 ? pixels[y * stride + x - 4] : 0
      const up = y > 0 ? pixels[(y - 1) * stride + x] : 0
      const upLeft = x >= 4 && y > 0 ? pixels[(y - 1) * stride + x - 4] : 0
      let value = line[x]
      if (filter === 1) value += left
      else if (filter === 2) value += up
      else if (filter === 3) value += (left + up) >> 1
      else if (filter === 4) {
        const p = left + up - upLeft
        const pa = Math.abs(p - left)
        const pb = Math.abs(p - up)
        const pc = Math.abs(p - upLeft)
        value += pa <= pb && pa <= pc ? left : pb <= pc ? up : upLeft
      }
      pixels[y * stride + x] = value & 0xff
    }
  }
  return {
    width,
    height,
    alphaAt: (x: number, y: number) => pixels[y * stride + x * 4 + 3],
  }
}

const DARK = '#1e1e1e' // --color-bg-dark
const PURPLE = '#8b7cf8' // --color-accent-dark

describe('brand mark', () => {
  it('draws the flame and the document in the palette purple', () => {
    for (const file of ['favicon.svg', 'icon.svg', 'mark.svg']) {
      const svg = read(file).toString('utf8')
      expect(svg, file).toContain(PURPLE)
      // One continuous flame stroke, the inner flick, the card and its rules.
      expect(svg.match(/<path /g)?.length ?? 0, file).toBeGreaterThanOrEqual(4)
      expect(svg, file).toContain('stroke-linecap="round"')
    }
  })

  it('keeps the icon artwork on the dark canvas so it reads on any tab', () => {
    for (const file of ['favicon.svg', 'icon.svg']) {
      expect(read(file).toString('utf8'), file).toContain(`fill="${DARK}"`)
    }
  })

  it('ships the mark itself with no backdrop, for docs and in-app use', () => {
    expect(read('mark.svg').toString('utf8')).not.toContain('<rect')
  })
})

describe('icons the platform picks up', () => {
  it('ships a PNG at every exact size a manifest may ask for', () => {
    const expected: Record<string, number> = {
      'icon-192.png': 192,
      'icon-512.png': 512,
      'icon-maskable-512.png': 512,
      'apple-touch-icon.png': 180,
    }
    for (const [file, px] of Object.entries(expected)) {
      const png = decodePng(file)
      expect({ width: png.width, height: png.height }, file).toEqual({ width: px, height: px })
      expect(statSync(resolve(ROOT, 'public', file)).size, file).toBeGreaterThan(1024)
    }
  })

  it('leaves the rounded corners transparent instead of white', () => {
    // qlmanage flattens SVG transparency onto white, so the build punches the
    // corners back out. A white corner is a visible square in every launcher.
    const png = decodePng('icon-512.png')
    expect(png.alphaAt(2, 2)).toBe(0)
    expect(png.alphaAt(256, 256)).toBe(255)
  })

  it('gives iOS an opaque icon (it applies its own corner mask)', () => {
    expect(decodePng('apple-touch-icon.png').alphaAt(1, 1)).toBe(255)
  })

  it('ships a multi-resolution favicon.ico for legacy tabs', () => {
    const buf = read('favicon.ico')
    expect(buf.readUInt16LE(0), 'ico reserved').toBe(0)
    expect(buf.readUInt16LE(2), 'ico type').toBe(1)
    const count = buf.readUInt16LE(4)
    expect(count).toBeGreaterThanOrEqual(3)
    const sizes = Array.from({ length: count }, (_, i) => buf[6 + i * 16] || 256)
    expect(sizes).toContain(16)
    expect(sizes).toContain(32)
  })

  it('links both favicon formats, the touch icon and the social card', () => {
    expect(html).toContain('href="/favicon.svg"')
    expect(html).toContain('href="/favicon.ico"')
    expect(html).toContain('rel="apple-touch-icon" href="/apple-touch-icon.png"')
    expect(html).toContain('content="https://firemd.app/og-image.png"')
    expect(html).toContain('name="twitter:card" content="summary_large_image"')
  })

  it('ships a social card at the size the crawlers crop for', () => {
    const png = decodePng('og-image.png')
    expect({ width: png.width, height: png.height }).toEqual({ width: 1200, height: 630 })
  })

  it('declares a maskable icon so Android can mask without clipping the flame', () => {
    expect(pwaConfig).toContain("src: '/icon-192.png'")
    expect(pwaConfig).toContain("src: '/icon-512.png'")
    expect(pwaConfig).toContain("src: '/icon-maskable-512.png'")
    expect(pwaConfig).toContain("purpose: 'maskable'")
  })
})
